// T-J1 S-WRONG member builder (L081, pane B). Applies the AMENDED §1 member rule of
// exo_memory/loop/tj1_registration_2026-09-22.md mechanically, and records every discretionary call it forced.
// Git is driven with execFileSync + argument arrays: no shell string ever carries a pattern.
// Reads only committed git objects. Opens no Jev ledger, no shadow store, no verdict ledger, no transcript.
'use strict';
const { execFileSync } = require('child_process');
const fs = require('fs');
const path = require('path');

const REPO = 'C:/Consonance/lighthouse';
const PIN = '201a03b4e3cb6771d5c166056ec9287ce0a0eb50';
const git = (args, opt = {}) => execFileSync('git', args, { cwd: REPO, encoding: 'utf8', maxBuffer: 256 * 1024 * 1024, ...opt });
const gitOk = (args) => { try { git(args, { stdio: ['ignore', 'pipe', 'ignore'] }); return true; } catch { return false; } };

// §2 table, verbatim word lists. D1: whole-word, case-insensitive, EXCEPT 'pathologi', which the table writes as a stem.
const CLASSES = [
  ['C1', ['figure', 'count', 'number', 'digest', 'sha', 'bytes', 'lines']],
  ['C2', ['landed', 'shipped', 'installed', 'live', 'verified', 'existed']],
  ['C3', ['offramp', 'rest', 'sleep', 'stop', 'ending', 'pathologi']],
];
const wordRe = (w) => (w === 'pathologi' ? new RegExp('\\bpathologi\\w*', 'i') : new RegExp('\\b' + w + '\\b', 'i'));
const prefixRe = (w) => new RegExp('\\b' + w, 'i');   // sensitivity reading only, never used to assign
function classOf(text, mk) { for (const [c, ws] of CLASSES) if (ws.some((w) => mk(w).test(text))) return c; return null; }

// §2 surface features for S-UNADJ (C2's list is the question's six words, verbatim).
const SURFACE = {
  C1: /\d/,
  C2: /\b(landed|shipped|installed|live|fixed|done)\b/i,
  C3: /\?(?=\s|$|["'”)*_])/,   // D8: "a sentence ending in ?" = a '?' followed by space, end, or closing punctuation
};

const PATHREF = /(?:^|[\s`(*"'“\[])((?:[\w.-]+\/)*[\w.-]+\.(?:md|js|rs|ps1|py|json|txt|ts|sh|html|toml|jsonl)):(\d+)(?:[-–](\d+))?/g;
const QUOTE = /"([^"\n]+)"|“([^”\n]+)”/g;
const RESOLVE_PREFIXES = ['', 'exo_memory/', 'consonance/tools/', 'consonance/hooks/', 'consonance/src-tauri/src/', 'dev/shell/hooks/', 'dev/shell/', 'dev/'];

const blameCache = new Map();   // "commit:path" -> [{commit, origLine, date}] indexed by final line (1-based)
function blame(commit, file) {
  const key = commit + ':' + file;
  if (blameCache.has(key)) return blameCache.get(key);
  const out = git(['blame', '--porcelain', commit, '--', file]);
  const rows = []; const meta = {};
  let cur = null;
  for (const l of out.split('\n')) {
    const h = /^([0-9a-f]{40}) (\d+) (\d+)/.exec(l);
    if (h) { cur = { commit: h[1], origLine: Number(h[2]), finalLine: Number(h[3]) }; continue; }
    if (cur && l.startsWith('committer-time ')) meta[cur.commit] = Number(l.slice(15));
    if (cur && l.startsWith('\t')) { cur.date = meta[cur.commit]; rows[cur.finalLine] = cur; cur = null; }
  }
  for (const r of rows) if (r && r.date == null) r.date = meta[r.commit];
  blameCache.set(key, rows); return rows;
}
const showCache = new Map();
function fileAt(commit, file) {
  const key = commit + ':' + file;
  if (!showCache.has(key)) showCache.set(key, git(['show', commit + ':' + file]).split(/\r?\n/));
  return showCache.get(key);
}

// ── 1. the universe, exactly the registration's command ─────────────────────────────────────────
const uraw = git(['grep', '-n', '-E', 'WRONG( #| \\+|[: ]+[0-9])', PIN, '--', 'exo_memory/librarian', 'exo_memory/journal']);
const ulines = uraw.split('\n').filter(Boolean);
const universe = ulines.map((l) => {
  const rest = l.slice(PIN.length + 1);
  const m = /^(.+?):(\d+):(.*)$/.exec(rest);
  return { path: m[1], line: Number(m[2]), text: m[3] };
});

const calls = [];   // discretionary calls actually exercised, with counts
const tally = (k) => { const c = calls.find((x) => x.id === k); c.used++; };
[
  ['D1', 'Class words matched whole-word, case-insensitive; "pathologi" alone as a stem (the table writes it so). A prefix reading is computed beside it for sensitivity and never assigns.'],
  ['D2', '"The adjudication line\'s own commit" = the commit git blame at the pinned commit attributes the line to. The unit is read from THAT commit\'s tree, at the line\'s number in that commit.'],
  ['D3', 'A quoted phrase must grep back to exactly one line OTHER THAN the adjudication line itself: the adjudication line quotes the phrase, so counting it would make "exactly one" unreachable for any surviving source.'],
  ['D4', 'A path:line locator is resolved at the adjudication commit by trying, in order, the path as written and under exo_memory/, consonance/tools/, consonance/hooks/, consonance/src-tauri/src/, dev/shell/hooks/, dev/shell/, dev/. More than one existing resolution = ambiguous.'],
  ['D5', 'A path:line RANGE (a-b, a≠b) locates a passage, not a sentence: not a locator. A range a-a is line a.'],
  ['D6', 'A line with several locators is a member only if they all resolve to ONE distinct line; two or more distinct lines = ambiguous, excluded.'],
  ['D7', '"Locates the erroneous sentence" is applied MECHANICALLY: a resolved locator is taken as locating it. No semantic check that the located line is the error rather than, e.g., the correction it quotes. Every member carries its locator and text so the non-author check can audit this.'],
  ['D8', 'C3\'s surface feature "a sentence ending in ?" = a "?" followed by whitespace, end of line, or closing punctuation.'],
  ['D9', 'S-UNADJ "same author\'s section" = the block between the nearest markdown headers (lines starting with #) around the unit in a .md file; the whole file otherwise.'],
  ['D10', 'S-UNADJ "within 7 days" = the candidate line\'s blame committer-time within 7 days of the unit line\'s, both at the unit\'s commit.'],
  ['D11', 'S-UNADJ candidates must be at least 3 lines from the member line, so the two ±1 units never overlap.'],
  ['D12', 'S-UNADJ "not cited by any universe line" = its text is not the text of any universe line and not the text of any universe line\'s resolved locator.'],
].forEach(([id, rule]) => calls.push({ id, rule, used: 0 }));

// ── 2. locate each universe line ────────────────────────────────────────────────────────────────
function resolvePath(commit, p) {
  const hits = RESOLVE_PREFIXES.map((pre) => pre + p).filter((cand, i, a) => a.indexOf(cand) === i && gitOk(['cat-file', '-e', commit + ':' + cand]));
  return hits;
}
const results = [];
for (const u of universe) {
  const b = blame(PIN, u.path)[u.line];
  const C = b.commit; const adjOrig = b.origLine;
  const cands = []; const notes = [];
  let m; PATHREF.lastIndex = 0;
  while ((m = PATHREF.exec(u.text))) {
    const p = m[1], a = Number(m[2]), z = m[3] ? Number(m[3]) : a;
    if (z !== a) { notes.push('range ' + p + ':' + a + '-' + z); tally('D5'); continue; }
    const hits = resolvePath(C, p); tally('D4');
    if (hits.length === 0) { notes.push('path not found at commit: ' + p); continue; }
    if (hits.length > 1) { notes.push('path ambiguous: ' + hits.join(' | ')); continue; }
    const lines = fileAt(C, hits[0]);
    if (a < 1 || a > lines.length) { notes.push('line out of range: ' + hits[0] + ':' + a); continue; }
    cands.push({ kind: 'path:line', value: p + ':' + a, path: hits[0], line: a });
  }
  QUOTE.lastIndex = 0;
  while ((m = QUOTE.exec(u.text))) {
    const phrase = (m[1] || m[2]).trim();
    if (!phrase) continue;
    let out = '';
    try { out = git(['grep', '-n', '-F', '-e', phrase, C, '--']); } catch { out = ''; }
    const hitsQ = out.split('\n').filter(Boolean).map((l) => {
      const r = l.slice(C.length + 1); const mm = /^(.+?):(\d+):/.exec(r);
      return mm ? { path: mm[1], line: Number(mm[2]) } : null;
    }).filter(Boolean).filter((h) => !(h.path === u.path && h.line === adjOrig));
    tally('D3');
    if (hitsQ.length === 1) cands.push({ kind: 'quote', value: phrase, path: hitsQ[0].path, line: hitsQ[0].line });
    else notes.push('quote greps to ' + hitsQ.length + ' other lines: "' + phrase.slice(0, 60) + '"');
  }
  const distinct = [...new Map(cands.map((c) => [c.path + ':' + c.line, c])).values()];
  const cls = classOf(u.text, wordRe); const clsPrefix = classOf(u.text, prefixRe);
  const r = { universe: u.path + ':' + u.line, adjudication_commit: C, adjudication_text: u.text.trim(), class: cls,
    class_under_prefix_reading: clsPrefix, locators: cands.map((c) => ({ kind: c.kind, value: c.value, resolves_to: c.path + ':' + c.line })), notes };
  if (distinct.length === 0) r.status = 'EXCLUDED: no locatable sentence';
  else if (distinct.length > 1) { r.status = 'EXCLUDED: ambiguous locators (' + distinct.length + ' distinct lines)'; tally('D6'); }
  else if (!cls) r.status = 'EXCLUDED: located, maps to no class';
  else {
    const d = distinct[0]; const lines = fileAt(C, d.path);
    r.status = 'MEMBER'; tally('D2'); tally('D7');
    r.unit = { path: d.path, line: d.line, commit: C, text: lines.slice(Math.max(0, d.line - 2), d.line + 1).join('\n') };
  }
  results.push(r);
}

// ── 3. S-UNADJ, one per member ──────────────────────────────────────────────────────────────────
const citedTexts = new Set(universe.map((u) => u.text.trim()));
for (const r of results) for (const l of r.locators) {
  const [p, ln] = [l.resolves_to.slice(0, l.resolves_to.lastIndexOf(':')), Number(l.resolves_to.slice(l.resolves_to.lastIndexOf(':') + 1))];
  const lines = fileAt(r.adjudication_commit, p); if (lines[ln - 1] != null) citedTexts.add(lines[ln - 1].trim());
}
for (const r of results.filter((x) => x.status === 'MEMBER')) {
  const { path: G, line: L, commit: C } = r.unit;
  const lines = fileAt(C, G); const bl = blame(C, G);
  const isMd = /\.md$/i.test(G);
  let lo = 1, hi = lines.length;
  if (isMd) {
    for (let i = L - 1; i >= 1; i--) if (/^#/.test(lines[i - 1])) { lo = i; break; }
    for (let i = L + 1; i <= lines.length; i++) if (/^#/.test(lines[i - 1])) { hi = i - 1; break; }
    tally('D9');
  }
  const tL = bl[L] ? bl[L].date : null;
  let best = null;
  for (let i = lo; i <= hi; i++) {
    const dist = Math.abs(i - L); if (dist < 3) continue;
    const t = lines[i - 1]; if (!SURFACE[r.class].test(t)) continue;
    if (citedTexts.has(t.trim())) continue;
    const ti = bl[i] ? bl[i].date : null;
    if (tL == null || ti == null || Math.abs(ti - tL) > 7 * 86400) continue;
    if (!best || dist < best.dist || (dist === best.dist && i < best.line)) best = { line: i, dist };
  }
  tally('D10'); tally('D11'); tally('D12'); if (r.class === 'C3') tally('D8');
  r.negative = best ? { path: G, line: best.line, commit: C, text: lines.slice(Math.max(0, best.line - 2), best.line + 1).join('\n') }
                    : null;
}

// ── 4. counts and the file ──────────────────────────────────────────────────────────────────────
const members = results.filter((r) => r.status === 'MEMBER');
const byReason = {}; for (const r of results.filter((x) => x.status !== 'MEMBER')) byReason[r.status] = (byReason[r.status] || 0) + 1;
const perClass = {}; for (const c of ['C1', 'C2', 'C3']) {
  const ms = members.filter((r) => r.class === c);
  perClass[c] = { positives: ms.length, negatives: ms.filter((r) => r.negative).length, members_without_a_negative: ms.filter((r) => !r.negative).length,
    rules: ms.length >= 20 && ms.filter((r) => r.negative).length >= 20 };
}
const located = results.filter((r) => !/^EXCLUDED: (no locatable|ambiguous)/.test(r.status)).length;
const sens = {}; for (const r of results) { const k = (r.class || 'none') + '→' + (r.class_under_prefix_reading || 'none'); if (r.class !== r.class_under_prefix_reading) sens[k] = (sens[k] || 0) + 1; }

module.exports = { results, members, byReason, perClass, located, universe, calls, sens };
if (require.main === module) {
  console.log(JSON.stringify({ universe: universe.length, located, members: members.length, perClass, byReason, sensitivity_prefix_reading: sens,
    calls_used: calls.map((c) => c.id + ':' + c.used).join(' ') }, null, 1));
}
